#!/usr/bin/env python3
"""Actual rocket, collision movement and persistent exposed room outside the original city core."""
from browser_support import Browser,ROOT
import time,json,hashlib
with Browser() as b:
 b.load();ev=b.ev;ev('RADE.game.start();globalThis.s=RADE.game.session;globalThis.w=s.world;s.sim.state.enemies.forEach(e=>e.deployed=false);s.campaign.law.wanted=0;true')
 target=ev('''(()=>{const tile=RADE.cityData.decode('-3,2');for(const b of tile.buildings){if(b.height<5||b.height>40||b.points.length>16)continue;for(let i=0;i<b.points.length;i++){const a=b.points[i],d=b.points[(i+1)%b.points.length],dx=d[0]-a[0],dz=d[1]-a[1],L=Math.hypot(dx,dz);if(L<7||L>35)continue;const x=(a[0]+d[0])/2,z=(a[1]+d[1])/2;for(const side of [-1,1]){const nx=-dz/L*side,nz=dx/L*side,px=x+nx*12,pz=z+nz*12,y=w.ground(px,pz);if(w.blocked(px,pz,.35,y,1.8)||w.water(px,pz)||Math.abs(y-w.ground(x,z))>.2)continue;const direction=[-nx,0,-nz],hit=w.ray([px,y+1.3,pz],direction,13);if(Math.abs(hit-11.85)>.3)continue;let clear=true;for(let t=0;t<11;t+=.5)if(w.blocked(px-nx*t,pz-nz*t,.32,y,1.8)){clear=false;break;}if(clear)return {id:b.id,x,z,px,pz,y,nx,nz,wall:i};}}}return null;})()''');assert target,'No suitable real external façade'
 ev('globalThis.target='+json.dumps(target)+';s.sim.relocate(target.px,target.pz,Math.atan2(-target.nx,target.nz));s.player.pitch=Math.atan2(1.25-1.62,12);true');time.sleep(.25);b.wait('!w.cityStream.pending',60);b.capture('city-facade-before.png')
 b.cmd('Input.dispatchKeyEvent',{'type':'keyDown','code':'Digit3','key':'3'});time.sleep(.12);b.cmd('Input.dispatchKeyEvent',{'type':'keyUp','code':'Digit3','key':'3'});time.sleep(.2);assert ev('s.sim.state.weapon===2')
 for event in ['mousePressed','mouseReleased']:b.cmd('Input.dispatchMouseEvent',{'type':event,'x':720,'y':450,'button':'left','clickCount':1})
 b.wait('w.cityStream.save().buildings.some(b=>String(b.id)===String(target.id))',12);time.sleep(.25);b.capture('city-facade-breach.png');assert ev('w.cityStream.geometry.some(m=>m.building===target.id&&m.interior)');assert ev('s.urban.bodies.some(q=>{const b=q.engine.body(q.handle);return b&&!b.lost&&Math.hypot(b.pos[0]-target.x,b.pos[2]-target.z)<12;})'),'Fragments are alive beyond the old physics bounds'
 # Walking is performed by real W, after the near explosion has settled briefly.
 time.sleep(1.2);ev('document.exitPointerLock?.();RADE.game.input.clear();s.player.yaw=Math.atan2(-target.nx,target.nz);s.player.pitch=0;true');time.sleep(.12);b.cmd('Input.dispatchKeyEvent',{'type':'keyDown','code':'KeyW','key':'w'});time.sleep(4.2);b.cmd('Input.dispatchKeyEvent',{'type':'keyUp','code':'KeyW','key':'w'});time.sleep(.2)
 result=ev('({x:s.player.x,y:s.player.y,z:s.player.z,hp:s.player.hp,progress:(s.player.x-target.x)*(-target.nx)+(s.player.z-target.z)*(-target.nz),yaw:s.player.yaw,target,save:w.cityStream.save(),bodies:s.urban.bodies.length,physics:s.urban.physicsZones})');b.capture('city-breach-walk-debug.png');result['blocking']=ev('({static:w.cityStream.blocked(s.player.x,s.player.z,.28,s.player.y,1.8),next:w.cityStream.blocked(s.player.x-target.nx*.4,s.player.z-target.nz*.4,.28,s.player.y,1.8),dynamic:w.dynamicBodies.filter(q=>Math.hypot(q.x-s.player.x,q.z-s.player.z)<4).map(q=>({x:q.x,z:q.z,a:q.a,b:q.b,minY:q.minY,maxY:q.maxY})),command:RADE.game.lastCommand})');assert result['progress']>.3,result;assert result['hp']>0;assert not ev('w.blocked(s.player.x,s.player.z,.28,s.player.y,1.8)');b.capture('city-room-entered.png')
 ev('globalThis.saved=s.save();RADE.game.save();true');assert ev('saved.city.buildings.some(b=>String(b.id)===String(target.id))');assert ev('(()=>{const restored=RADE.session.create({pedestrians:0,saved,now:saved.savedAt}),ok=restored.world.cityStream.save().buildings.some(b=>String(b.id)===String(target.id))&&!restored.world.blocked(s.player.x,s.player.z,.28,s.player.y,1.8);restored.sim.dispose();return ok;})()');assert not ev('RADE.game.errors')
 # Ten seconds after all streamed construction finishes, using the agreed scenic view.
 ev('globalThis.lm=w.landmarks;const free=w.freeNear(lm.center.x+130,lm.center.z-110,.34);s.sim.relocate(free[0],free[1],0);s.campaign.law.wanted=0;s.weather.setHour(23);globalThis.camPos=[lm.center.x+130,lm.groundLevel+49,lm.center.z-110];const target=[lm.center.x-6,lm.groundLevel+29,lm.center.z],d=target.map((v,i)=>v-camPos[i]);RADE.game.camera={pos:camPos,yaw:Math.atan2(d[0],-d[2]),pitch:Math.atan2(d[1],Math.hypot(d[0],d[2])),fov:62,near:.15,overlayNear:.035,far:26000,allStatic:true,chunked:true};true');time.sleep(.25);b.wait('!w.cityStream.pending',90);time.sleep(.5)
 ev("""globalThis.gpuProbe={samples:[],pending:[],disjoint:0};const gl=RADE.game.renderer.gl,ext=gl.getExtension('EXT_disjoint_timer_query_webgl2');gpuProbe.available=!!ext;if(ext){const original=RADE.game.renderer.draw;gpuProbe.finish=()=>{RADE.game.renderer.draw=original;gpuProbe.poll();gpuProbe.pending.forEach(q=>gl.deleteQuery(q));gpuProbe.pending=[];};gpuProbe.poll=()=>{if(gl.getParameter(ext.GPU_DISJOINT_EXT)){gpuProbe.disjoint++;gpuProbe.pending.forEach(q=>gl.deleteQuery(q));gpuProbe.pending=[];return;}for(let i=gpuProbe.pending.length-1;i>=0;i--){const q=gpuProbe.pending[i];if(gl.getQueryParameter(q,gl.QUERY_RESULT_AVAILABLE)){gpuProbe.samples.push(gl.getQueryParameter(q,gl.QUERY_RESULT)/1e6);gl.deleteQuery(q);gpuProbe.pending.splice(i,1);}}};RADE.game.renderer.draw=function(...args){gpuProbe.poll();if(gpuProbe.pending.length>=12)return original.apply(this,args);const q=gl.createQuery();gl.beginQuery(ext.TIME_ELAPSED_EXT,q);try{return original.apply(this,args);}finally{gl.endQuery(ext.TIME_ELAPSED_EXT);gpuProbe.pending.push(q);}};}RADE.game.samples.length=0;RADE.game.cpuSamples.length=0;true""")
 time.sleep(10);perf=ev("""(()=>{gpuProbe.finish?.();const a=gpuProbe.samples.slice().sort((x,y)=>x-y);return {scene:'Bonne-Mère at 23:00, loaded chunks, scenic camera',durationSeconds:10,metrics:RADE.game.metrics(),stream:{...w.cityStream.stats},gpu:gpuProbe.available?{available:true,extension:'EXT_disjoint_timer_query_webgl2',n:a.length,p50Ms:a[Math.floor(a.length*.5)],p95Ms:a[Math.floor(a.length*.95)],disjointEvents:gpuProbe.disjoint}:{available:false,reason:'GPU timer query extension unavailable; frame interval is not reported as GPU duration'}};})()""");b.capture('bonne-mere-roads-after.png');assert not ev('RADE.game.errors')
 report={'checks':['Clic réel au lance-roquettes contre une façade OSM hors cœur','Brèche et pièce polygonale visibles ; débris physiques vivants hors anciennes limites','Marche W à travers la façade et état joueur libre','Ouverture inscrite dans la sauvegarde et restaurée dans une nouvelle session réelle'],'target':target,'result':result,'bonneMerePerformance':perf,'errors':ev('RADE.game.errors'),'fixture':'Position de départ, façade et orientation initiale de marche préparées ; ennemis de mission désactivés et menace initiale remise à zéro pour isoler la destruction ; capture souris relâchée après le tir. Tir et marche par entrées réelles ; aucune téléportation durant le franchissement. Pièce générique procédurale au RDC, pas un commerce réel reconstitué.','buildSha256':hashlib.sha256((ROOT/'dist/index.html').read_bytes()).hexdigest()};(ROOT/'docs/city-destruction-browser.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps(report,ensure_ascii=False,indent=2),flush=True)
